\question{What is the sum $1 + 2 + 3 + \cdots + 50$?}
\begin{subheading}{Prompt}
$$\sum_{k=1}^{50} k$$
\end{subheading}
\begin{subheading}{Thought}
\begin{itemize}
\item Identify the formula for the sum of the first $n$ integers using Gauss's method.
$$\sum_{k=1}^{n} k = \frac{n(n+1)}{2}$$
\item Substitute $n=50$ into the formula.
$$\frac{50 \cdot 51}{2}$$
\item Perform the arithmetic operations.
$$\frac{2550}{2} = 1275$$
\end{itemize}
\end{subheading}
\begin{subheading}{Final}
$$\boxed{1275}$$
\end{subheading}

\question{How many positive divisors does $360$ have?}
\begin{subheading}{Prompt}
$$\tau(360)$$
\end{subheading}
\begin{subheading}{Thought}
\begin{itemize}
\item Prime factorize $360$.
$$360 = 2^3 \cdot 3^2 \cdot 5^1$$
\item Apply the divisor counting formula $(a+1)(b+1)(c+1)$.
$$(3+1)(2+1)(1+1)$$
\item Calculate the product.
$$4 \cdot 3 \cdot 2 = 24$$
\end{itemize}
\end{subheading}
\begin{subheading}{Final}
$$\boxed{24}$$
\end{subheading}

\question{Find the last digit of $7^{100}$.}
\begin{subheading}{Prompt}
$$7^{100} \pmod{10}$$
\end{subheading}
\begin{subheading}{Thought}
\begin{itemize}
\item Calculate the powers of $7$ to find the cycle length.
$7^1 \equiv 7, \quad 7^2 \equiv 49 \equiv 9, \quad 7^3 \equiv 63 \equiv 3, \quad 7^4 \equiv 21 \equiv 1 \pmod{10}$
\item Determine the period of the last cycle.
$$\text{Cycle} = \{7, 9, 3, 1\} \quad (\text{Period } = 4)$$
\item Find the remainder of the exponent modulo the period.
$$100 \div 4 = 25 \text{ remainder } 0 \implies 100 \equiv 0 \pmod{4}$$
\item The remainder corresponds to the last digit in the cycle (digit 1).
$$\text{Last digit is } 1$$
\end{itemize}
\end{subheading}
\begin{subheading}{Final}
$$\boxed{1}$$
\end{subheading}

\question{A right triangle has legs of length $5$ and $12$. What is the length of the hypotenuse?}
\begin{subheading}{Prompt}
$$c^2 = a^2 + b^2$$
\end{subheading}
\begin{subheading}{Thought}
\begin{itemize}
\item Apply the Pythagorean theorem with sides $a=5$ and $b=12$.
$$h^2 = 5^2 + 12^2$$
\item Simplify the squares and sum.
$$25 + 144 = 169$$
\item Take the square root to find the hypotenuse.
$$h = \sqrt{169} = 13$$
\end{itemize}
\end{subheading}
\begin{subheading}{Final}
$$\boxed{13}$$
\end{subheading}

